import {registerHooks} from "node:module";
registerHooks({resolve(specifier,context,next) {
  if (context.parentURL?.includes("/src/lib/vigia/recount-vision") && /^\.\/[a-z-]+$/.test(specifier))
    return next(specifier + ".ts",context);
  return next(specifier,context);
}});
if (process.env.GROQ_API_KEY) {
  const {readInventoryDocument} = await import("../src/lib/vigia/recount-vision-provider.ts");
  try {
    const rows = await readInventoryDocument("data:image/jpeg;base64,");
    const expected = [["070330905191","4"],["AMPM1007","74"],["001220003411","0"],["000001234567","22"],["641194000010","105"],["09010026","9"]];
    const matching = expected.filter(([code,system]) => rows?.some(row => row.code === code && row.system === system)).length;
    const notes = rows?.some(row => row.code === "AMPM1007" && row.suggestedPhysical === "74");
    console.log("[recount-vision-check]", {rows: rows?.length ?? 0, matching, notes: Boolean(notes), noPhysicalAutofill: rows?.every(row => row.physical === "")});
  } catch (error) {
    const code = /^[\w-]{1,40}$/.test(error?.code ?? "") ? error.code : null;
    console.log("[recount-vision-check] provider failed", error?.status ?? null, code);
  }
}
